const LANGS = ["UZ", "RU", "KK", "AR", "TR"] as const
export const CONSOLE_MESSAGES: Record<string, Partial<Record<"EN" | (typeof LANGS)[number], string>>> = Object.fromEntries(
  rows.map(([en, ...rest]) => [en, { EN: en, ...Object.fromEntries(LANGS.map((code, i) => [code, rest[i]])) }]),
)
// Server errors are lowercase IDs; show the helpful English sentence instead of the raw ID.
for (const [id, entry] of Object.entries(CONSOLE_MESSAGES)) if (/^[a-z]/.test(id) && !["month", "extra", "pcs", "try-ons", "brands", "whole brand", "one branch", "cashier or kiosk"].includes(id)) entry.EN = ({
  "branch limit reached": "Branch limit reached. Upgrade the plan.", "device limit reached": "Mirror limit reached. Upgrade the plan.",
  "active subscription required": "An active subscription is required. Check the payment.", "insufficient stock": "Not enough stock.",
  "invalid user": "Check the email, password (at least 12 characters) and branch.", "current password is incorrect": "The current password is incorrect.",
  "permission denied": "You do not have permission for this action.", "operation could not be completed": "The operation could not be completed. Check for duplicates.",
  "invalid product or variants": "Check the product details (name, price, SKU, sizes and colors).",
  "mirror try-on limit reached": "This mirror has used all its try-ons.", "this sign-in email is already used": "This sign-in email is already used.",
} as Record<string, string>)[id] ?? id
